"""MLflow's OSS Unity Catalog registry store, as `mlflow server` calls it (generated by trestle).

The server passes its request defaults (an empty filter, an empty ordering) where the store
expects them unset, and rejects them as unsupported; normalize them back to unset.
"""

from mlflow.store._unity_catalog.registry.uc_oss_rest_store import UnityCatalogOssStore


class UcRegistryStore(UnityCatalogOssStore):
    def search_registered_models(
        self, filter_string=None, max_results=None, order_by=None, page_token=None
    ):
        return super().search_registered_models(
            filter_string or None, max_results, order_by or None, page_token
        )

    def search_model_versions(
        self, filter_string=None, max_results=None, order_by=None, page_token=None
    ):
        return super().search_model_versions(
            filter_string, max_results, order_by or None, page_token
        )
